using ClipBridge;
using Microsoft.Win32;
sealed partial class BridgeWindow
{
    private void BuildDashboard(){Font=new Font("Microsoft YaHei UI",10);BackColor=Color.FromArgb(245,246,247);Size=new Size(850,680);MinimumSize=new Size(790,600);StartPosition=FormStartPosition.CenterScreen;
        var side=new Panel{Dock=DockStyle.Left,Width=150,BackColor=Color.White};var brand=MakeLabel("ClipBridge",18,FontStyle.Bold);brand.Location=new Point(15,30);side.Controls.Add(brand);for(int i=0;i<3;i++){int index=i;var nav=MakeButton(new[]{"状态","配置","设置"}[i],false);nav.SetBounds(12,110+i*55,126,42);nav.Click+=(_,_)=>{selectedPage=index;RenderPage();};side.Controls.Add(nav);}Controls.Add(page);Controls.Add(side);uiTimer.Tick+=(_,_)=>{if(Visible)RenderPage();};uiTimer.Start();RenderPage();}
    private void OpenDashboard(){Show();WindowState=FormWindowState.Normal;Activate();}
    private void RenderPage(){if(IsDisposed)return;page.SuspendLayout();foreach(Control child in page.Controls.Cast<Control>().ToArray())child.Dispose();var stack=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Width=Math.Max(540,page.ClientSize.Width-48)};int width=stack.Width;var title=MakeLabel(new[]{"状态","配置","设置"}[selectedPage],23,FontStyle.Bold);title.Margin=new Padding(0,0,0,20);stack.Controls.Add(title);
        if(selectedPage<2){if(data.Profiles.Count==0)stack.Controls.Add(MakeLabel("暂无配置",15));foreach(var p in data.Profiles){var card=new Panel{BackColor=Color.White,Size=new Size(width,145),Margin=new Padding(0,0,0,12)};var name=MakeLabel(p.Title,15,FontStyle.Bold);name.Location=new Point(18,16);name.MaximumSize=new Size(width-200,30);card.Controls.Add(name);var enabled=new CheckBox{Text="开启",Checked=p.Enabled,AutoSize=true,Location=new Point(width-170,20)};enabled.CheckedChanged+=(_,_)=>{p.Enabled=enabled.Checked;if(!p.Enabled){p.State.Pending=null;if(data.Clipboard is{} batch&&!data.Profiles.Any(other=>other.Enabled&&other.Group==p.Group)&&!batch.DoneGroups.Contains(p.Group))batch.DoneGroups.Add(p.Group);}Save();Reconcile();};card.Controls.Add(enabled);var remove=MakeButton("删除",false);remove.SetBounds(width-92,12,72,33);remove.Click+=async(_,_)=>{if(MessageBox.Show(this,"删除此配置？其他配置不受影响。","ClipBridge",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;p.Enabled=false;p.State.Pending=null;data.Tombstones[p.Config.Pair]=p.State;data.Profiles.Remove(p);if(data.Clipboard is{} batch){batch.Targets.Remove(p.Config.Pair);if(!data.Profiles.Any(other=>other.Group==p.Group))batch.Groups.Remove(p.Group);if(batch.Targets.Count==0&&batch.Groups.Count==0)data.Clipboard=null;}hub.RemoveRoute(p.Config.Pair);var oldConfig=Path.Combine(folder,"profiles",p.Config.Pair,"config.bin");File.Delete(oldConfig);Save();Reconcile();RenderPage();await Task.CompletedTask;};card.Controls.Add(remove);
                string last=p.LastSync==0?"暂无同步记录":DateTimeOffset.FromUnixTimeMilliseconds(p.LastSync).LocalDateTime.ToString("MM-dd HH:mm:ss");var detail=MakeLabel(p.Config.Transport+" · "+(p.Enabled?(paused?"全部已暂停":p.Status):"已关闭")+"\n最后同步  "+last+"\n"+p.Config.Server,9);detail.Location=new Point(20,55);detail.MaximumSize=new Size(width-40,80);card.Controls.Add(detail);stack.Controls.Add(card);}
            var actions=new FlowLayoutPanel{Size=new Size(width,48)};var add=MakeButton("添加配置",true);add.Size=new Size(130,40);add.Click+=(_,_)=>AddPairing();actions.Controls.Add(add);var import=MakeButton("导入配置",false);import.Size=new Size(130,40);import.Click+=(_,_)=>Import();actions.Controls.Add(import);var files=MakeButton("发送文件",false);files.Size=new Size(130,40);files.Click+=async(_,_)=>await ChooseFiles();actions.Controls.Add(files);stack.Controls.Add(actions);
        }else{var startup=new CheckBox{Text="开机自启动（驻留托盘）",AutoSize=true,Checked=AutoStart()};startup.CheckedChanged+=(_,_)=>SetAutoStart(startup.Checked);stack.Controls.Add(startup);var shell=new CheckBox{Text="资源管理器右键：通过 ClipBridge 发送",AutoSize=true,Checked=ShellEnabled(),Margin=new Padding(0,15,0,20)};shell.CheckedChanged+=(_,_)=>SetShell(shell.Checked);stack.Controls.Add(shell);var folderLabel=MakeLabel("文件接收目录\n"+data.ReceiveDirectory,10);folderLabel.MaximumSize=new Size(width,60);stack.Controls.Add(folderLabel);var browse=MakeButton("修改接收目录",false);browse.Size=new Size(170,40);browse.Click+=(_,_)=>{using var dialog=new FolderBrowserDialog{SelectedPath=data.ReceiveDirectory};if(dialog.ShowDialog(this)==DialogResult.OK){data.ReceiveDirectory=dialog.SelectedPath;Save();}};stack.Controls.Add(browse);stack.Controls.Add(MakeLabel("版本  0.5.0 · 单文件上限 100 MB",10));}page.Controls.Add(stack);page.ResumeLayout();}
    private void AddPairing(){using var choice=new Form{Text="添加配置",ClientSize=new Size(350,180),FormBorderStyle=FormBorderStyle.FixedDialog,StartPosition=FormStartPosition.CenterParent};foreach(bool relay in new[]{true,false}){var button=MakeButton(relay?"ClipBridge 中转":"WebDAV",relay);button.SetBounds(25,relay?30:100,300,45);button.Click+=(_,_)=>choice.DialogResult=relay?DialogResult.Yes:DialogResult.No;choice.Controls.Add(button);}var result=choice.ShowDialog(this);try{if(result==DialogResult.No){using var dav=new WebDavWizard();if(dav.ShowDialog(this)==DialogResult.OK&&dav.SelectedConfig is{} c)UsePairing(c);}else if(result==DialogResult.Yes){using var wizard=new PairingWizard(null,folder,data.Profiles.Count>0);if(wizard.ShowDialog(this)==DialogResult.OK&&wizard.SelectedConfig is{} c){UsePairing(c);File.Delete(Path.Combine(folder,"pending-pairing.bin"));}}}catch{MessageBox.Show(this,"配置保存失败；请检查是否重复导入同一配对。","ClipBridge");}}
    internal static Label MakeLabel(string text,float size,FontStyle style=FontStyle.Regular)=>new(){Text=text,AutoSize=true,Font=new Font("Microsoft YaHei UI",size,style),ForeColor=Color.FromArgb(35,39,43),BackColor=Color.Transparent};
    internal static Button MakeButton(string text,bool primary)=>new(){Text=text,FlatStyle=FlatStyle.Flat,Cursor=Cursors.Hand,Font=new Font("Microsoft YaHei UI",10),BackColor=primary?Color.FromArgb(8,127,115):Color.FromArgb(237,240,240),ForeColor=primary?Color.White:Color.FromArgb(55,64,64),FlatAppearance={BorderSize=0},UseVisualStyleBackColor=false};
    private static bool AutoStart(){using var key=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run");return key?.GetValue("ClipBridge") is string;}
    private void SetAutoStart(bool value){try{using var key=Registry.CurrentUser.CreateSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run");if(value)key.SetValue("ClipBridge","\""+Application.ExecutablePath+"\" --startup");else key.DeleteValue("ClipBridge",false);}catch{MessageBox.Show(this,"无法修改自启动设置。");}}
    private static bool ShellEnabled(){using var key=Registry.CurrentUser.OpenSubKey(@"Software\Classes\*\shell\ClipBridge\command");return key?.GetValue("") is string;}
    private void SetShell(bool enabled){try{const string path=@"Software\Classes\*\shell\ClipBridge";if(!enabled){Registry.CurrentUser.DeleteSubKeyTree(path,false);return;}using var key=Registry.CurrentUser.CreateSubKey(path);key.SetValue("","通过 ClipBridge 发送");key.SetValue("Icon",Application.ExecutablePath);key.SetValue("MultiSelectModel","Player");using var command=key.CreateSubKey("command");command.SetValue("","\""+Application.ExecutablePath+"\" --send \"%1\"");}catch{MessageBox.Show(this,"无法修改右键菜单。");}}
}
